	// 占用累计会超过实物 M（若按加法核算还会 int 回绕）。必须返回库存不足，
	// 不能成功，也不能返回参数非法。
	if _, err := s.Reserve("c2", "r2", "part1", M-1, expiryOK, nowOK); !errors.Is(err, ErrInsufficientStock) {
